{-# LANGUAGE OverloadedStrings #-}
module ComboUpsertSql (comboUpsertSql) where
import Database.PostgreSQL.Simple.Types (Query)
comboUpsertSql :: Query
comboUpsertSql = "INSERT INTO combos (combo_uuid, strategy_id, symbol, interval, objective, source, final_equity, annualized_return, score, open_threshold, close_threshold, params_json, metrics_json, operation_count, created_at_ms, updated_at_ms) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?::jsonb, ?::jsonb, ?, ?, ?) ON CONFLICT (combo_uuid) DO UPDATE SET strategy_id = EXCLUDED.strategy_id, symbol = EXCLUDED.symbol, interval = EXCLUDED.interval, objective = EXCLUDED.objective, source = EXCLUDED.source, final_equity = EXCLUDED.final_equity, annualized_return = EXCLUDED.annualized_return, score = EXCLUDED.score, open_threshold = EXCLUDED.open_threshold, close_threshold = EXCLUDED.close_threshold, params_json = EXCLUDED.params_json, metrics_json = CASE WHEN combos.metrics_json IS NOT NULL AND jsonb_exists(combos.metrics_json, 'live') AND (EXCLUDED.metrics_json IS NULL OR NOT jsonb_exists(EXCLUDED.metrics_json, 'live') OR COALESCE((EXCLUDED.metrics_json->'live'->>'operationCount')::numeric, 0) < COALESCE((combos.metrics_json->'live'->>'operationCount')::numeric, 0)) THEN COALESCE(EXCLUDED.metrics_json, '{}'::jsonb) || jsonb_build_object('live', combos.metrics_json->'live') ELSE EXCLUDED.metrics_json END, operation_count = EXCLUDED.operation_count, created_at_ms = COALESCE(combos.created_at_ms, EXCLUDED.created_at_ms), updated_at_ms = EXCLUDED.updated_at_ms"
